(3894275, 549209, 41357, '<td valign="top">I know the feeling</td>', 'I know the feeling', '2007-07-11 15:56:28.000000', NULL, 1),
(3894320, 550385, 43774, '<td valign="top">House fire? Yep, been there....my house was completely destroyed by fire in 1994, I literally only had the clothes on my back. It was a nightmare, believe me.<br/> <br/>Your photo shows the destruction but I find the colours odd. A purple cast in some areas and a green cast in other areas.</td>', 'House fire? Yep, been there....my house was completely destroyed by fire in 1994, I literally only had the clothes on my back. It was a nightmare, believe me. Your photo shows the destruction but I find the colours odd. A purple cast in some areas and a green cast in other areas.', '2007-07-11 16:11:19.000000', NULL, 1),
(3894322, 552963, 43774, '<td valign="top">Ack!!! That would be my nightmare, I hate spiders (or are they ants?).</td>', 'Ack!!! That would be my nightmare, I hate spiders (or are they ants?).', '2007-07-11 16:12:07.000000', NULL, 1),
(3894324, 552631, 43774, '<td valign="top">Cool photo but your title doesn''t go with it. You could have named it back street alley or alley at night, that would be scary enough, especially since there is a person there, who knows, he could be an axe murderer!</td>', 'Cool photo but your title doesn''t go with it. You could have named it back street alley or alley at night, that would be scary enough, especially since there is a person there, who knows, he could be an axe murderer!', '2007-07-11 16:13:11.000000', NULL, 1),
(3894326, 552758, 43774, '<td valign="top">Would be very cool if there were a person on that thing instead of birds but I guess that wasn''t possible.</td>', 'Would be very cool if there were a person on that thing instead of birds but I guess that wasn''t possible.', '2007-07-11 16:13:57.000000', NULL, 1),
(3894327, 551169, 43774, '<td valign="top">Very effective lighting!!!</td>', 'Very effective lighting!!!', '2007-07-11 16:14:09.000000', NULL, 1),
(3894330, 552643, 43774, '<td valign="top">The lighting and grain really work well here</td>', 'The lighting and grain really work well here', '2007-07-11 16:14:33.000000', NULL, 1),
(3894336, 552565, 43774, '<td valign="top">Creepy!</td>', 'Creepy!', '2007-07-11 16:16:00.000000', NULL, 1),
(3894340, 552579, 43774, '<td valign="top">I''m looking at the pretty bed wondering what the nightmare is....then I see him! Cool.</td>', 'I''m looking at the pretty bed wondering what the nightmare is....then I see him! Cool.', '2007-07-11 16:16:37.000000', NULL, 1),
(3894345, 552938, 43774, '<td valign="top">Poor Alli! I think it would be more realistic if she were under the covers curled up and looking like she were asleep. Now it looks too much like a staged photo. If there were a bit more light on her it would be better too.</td>', 'Poor Alli! I think it would be more realistic if she were under the covers curled up and looking like she were asleep. Now it looks too much like a staged photo. If there were a bit more light on her it would be better too.', '2007-07-11 16:18:06.000000', NULL, 1),
(3894347, 552059, 43774, '<td valign="top">Goodness, where does one find this?! Very creepy, great for this challenge.</td>', 'Goodness, where does one find this?! Very creepy, great for this challenge.', '2007-07-11 16:18:51.000000', NULL, 1),
(3894348, 552846, 37252, '<td valign="top">personally I like snakes so they don''t give me nightmares, but many truly are frightened by these creatures. I think you did well with the composition. It'' a bit noisy, but in a persons sleep it may be that way. I would have loved to see but is beyond your control would have been the tongue sticking out. The lighting is a bit flat, but overall a nice shot.</td>', 'personally I like snakes so they don''t give me nightmares, but many truly are frightened by these creatures. I think you did well with the composition. It'' a bit noisy, but in a persons sleep it may be that way. I would have loved to see but is beyond your control would have been the tongue sticking out. The lighting is a bit flat, but overall a nice shot.', '2007-07-11 16:19:38.000000', NULL, 1),
(3894352, 552287, 43774, '<td valign="top">Eeek!!! Great job, I love that you used an old fashioned carriage and doll for this photo. The post processing and DOF are perfect.</td>', 'Eeek!!! Great job, I love that you used an old fashioned carriage and doll for this photo. The post processing and DOF are perfect.', '2007-07-11 16:20:28.000000', NULL, 1),
(3894353, 551297, 37252, '<td valign="top">The image is very flat to me. I don''t get the overwhelming fear of the ship plowing into me as I think was your intention. The tight crop on the top does not help me either.</td>', 'The image is very flat to me. I don''t get the overwhelming fear of the ship plowing into me as I think was your intention. The tight crop on the top does not help me either.', '2007-07-11 16:20:59.000000', NULL, 1),
(3894360, 552631, 37252, '<td valign="top">The nightmare would be what? Dark tunnels? The train that the title indicates but the image does not? I just don''t get the sense of a nightmare here at all.</td>', 'The nightmare would be what? Dark tunnels? The train that the title indicates but the image does not? I just don''t get the sense of a nightmare here at all.', '2007-07-11 16:22:38.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3894365, 552088, 37252, '<td valign="top">Very good. The composition and lighting along with soft focus truly reflect this as a nightmare type image.</td>', 'Very good. The composition and lighting along with soft focus truly reflect this as a nightmare type image.', '2007-07-11 16:23:44.000000', NULL, 1),
(3894374, 552808, 37252, '<td valign="top">Due to very poor lighting and focus, a cat can hardly be detected here. Even if I could see a cat, how does that convey nightmares?<br/>I rarely give out a score below 4, but in this case I have no choice as I do not see this as a salvageable image. Sorry.</td>', 'Due to very poor lighting and focus, a cat can hardly be detected here. Even if I could see a cat, how does that convey nightmares?I rarely give out a score below 4, but in this case I have no choice as I do not see this as a salvageable image. Sorry.', '2007-07-11 16:25:25.000000', NULL, 1),
(3894380, 551212, 37252, '<td valign="top">Humorous and well done technically. A bit bizarre of a nightmare.</td>', 'Humorous and well done technically. A bit bizarre of a nightmare.', '2007-07-11 16:26:43.000000', NULL, 1),
(3894383, 551212, 80967, '<td valign="top">very funny, love the lighting</td>', 'very funny, love the lighting', '2007-07-11 16:27:22.000000', NULL, 1),
(3894386, 552669, 37252, '<td valign="top">Love the soft focus here, and the expression on the face is great. Nice job with the lighting. The bubbles add to the reality of the image.</td>', 'Love the soft focus here, and the expression on the face is great. Nice job with the lighting. The bubbles add to the reality of the image.', '2007-07-11 16:27:51.000000', NULL, 1),
(3894390, 550858, 37252, '<td valign="top">The image appears to have a bit of noise to it that I don''t care for. Nice stop action with the shutter speed.</td>', 'The image appears to have a bit of noise to it that I don''t care for. Nice stop action with the shutter speed.', '2007-07-11 16:28:36.000000', NULL, 1),
(3894396, 552963, 37252, '<td valign="top">Hmmm - well the fake bugs look fake to me. I am not feeling convinced here. Not sure what the lipstick look is all about either as obviously this is a man.</td>', 'Hmmm - well the fake bugs look fake to me. I am not feeling convinced here. Not sure what the lipstick look is all about either as obviously this is a man.', '2007-07-11 16:30:04.000000', NULL, 1),
(3894401, 552525, 37252, '<td valign="top">I myself have never had a nightmare that I was wrapped in saran wrap. lol <br/>Good expression</td>', 'I myself have never had a nightmare that I was wrapped in saran wrap. lol Good expression', '2007-07-11 16:30:57.000000', NULL, 1),
(3894409, 550385, 37252, '<td valign="top">The image is a bit flat. Perhaps shooting it from another perspective and with the sun at a lower level in the sky would help.</td>', 'The image is a bit flat. Perhaps shooting it from another perspective and with the sun at a lower level in the sky would help.', '2007-07-11 16:32:00.000000', NULL, 1),
(3894412, 552960, 37252, '<td valign="top">The lighting is too harsh, and the details of the cats eye not clear enough.</td>', 'The lighting is too harsh, and the details of the cats eye not clear enough.', '2007-07-11 16:32:33.000000', NULL, 1),
(3894416, 549182, 37252, '<td valign="top">This would be a nightmare to someone who loves the bottle.</td>', 'This would be a nightmare to someone who loves the bottle.', '2007-07-11 16:33:46.000000', NULL, 1),
(3894419, 552789, 37252, '<td valign="top">Cute idea - I think as a child we all heard bumps in the night. I would have liked to see the young girl trying to see what was under the bed rather than looking at the camera.</td>', 'Cute idea - I think as a child we all heard bumps in the night. I would have liked to see the young girl trying to see what was under the bed rather than looking at the camera.', '2007-07-11 16:35:04.000000', NULL, 1),
(3894421, 552025, 37252, '<td valign="top">I don''t see a nightmare picture here - I see fireworks only.</td>', 'I don''t see a nightmare picture here - I see fireworks only.', '2007-07-11 16:35:43.000000', NULL, 1),
(3894424, 552843, 80967, '<td valign="top">nice touch with the ring</td>', 'nice touch with the ring', '2007-07-11 16:36:20.000000', NULL, 1),
(3894425, 550924, 37252, '<td valign="top">Great idea! I loved that movie. I like the way you shot this with the girls backlit.</td>', 'Great idea! I loved that movie. I like the way you shot this with the girls backlit.', '2007-07-11 16:36:27.000000', NULL, 1),
(3894429, 552733, 37252, '<td valign="top">Crop seems a bit too tight. I would have liked to see more of the cemetery</td>', 'Crop seems a bit too tight. I would have liked to see more of the cemetery', '2007-07-11 16:37:20.000000', NULL, 1),
(3894432, 552383, 37252, '<td valign="top">I really don''t care for the composition on this one, or the drawing out of the skull. I feel you tried to do too much here.</td>', 'I really don''t care for the composition on this one, or the drawing out of the skull. I feel you tried to do too much here.', '2007-07-11 16:38:52.000000', NULL, 1),
(3894435, 552491, 37252, '<td valign="top">Nice shot of fireworks, I just don''t see it fitting into the Nightmares category.</td>', 'Nice shot of fireworks, I just don''t see it fitting into the Nightmares category.', '2007-07-11 16:39:27.000000', NULL, 1),
(3894437, 551856, 37252, '<td valign="top">I don''t see the nightmare, just a snapshot of a car in the rain.</td>', 'I don''t see the nightmare, just a snapshot of a car in the rain.', '2007-07-11 16:39:51.000000', NULL, 1),
(3894447, 549797, 37252, '<td valign="top">I''m one who fears the dentist of modern days - this old dentist chair and tools is truly frightening. lol</td>', 'I''m one who fears the dentist of modern days - this old dentist chair and tools is truly frightening. lol', '2007-07-11 16:42:47.000000', NULL, 1),
(3894450, 549399, 37252, '<td valign="top">Spider nightmares! Nice macro work</td>', 'Spider nightmares! Nice macro work', '2007-07-11 16:43:35.000000', NULL, 1),
(3894457, 549369, 50695, '<td valign="top">The image per se doesn''t do much for me, but the camera shake does at least add some quirkiness to it. What''s nice is the title, which is so evocative and causes me to look again, finding shapes and characters and emotion in the squiggly lines of light.</td>', 'The image per se doesn''t do much for me, but the camera shake does at least add some quirkiness to it. What''s nice is the title, which is so evocative and causes me to look again, finding shapes and characters and emotion in the squiggly lines of light.', '2007-07-11 16:45:08.000000', NULL, 1),
(3894458, 552982, 37252, '<td valign="top">I think I know what you were after - the soft focus like in a dream. There is a lot of blur though which is not the same as soft focus. The lighting seems too harsh on the face</td>', 'I think I know what you were after - the soft focus like in a dream. There is a lot of blur though which is not the same as soft focus. The lighting seems too harsh on the face', '2007-07-11 16:45:19.000000', NULL, 1),
(3894463, 552684, 50695, '<td valign="top">I don''t feel anything nightmarish about this. It''s a decent macro, though, with interesting OOF shapes and nice colors.</td>', 'I don''t feel anything nightmarish about this. It''s a decent macro, though, with interesting OOF shapes and nice colors.', '2007-07-11 16:46:14.000000', NULL, 1),
(3894464, 551432, 37252, '<td valign="top">You picked a hard subject to portray as a nightmare. I can see the portrait as someone who may be disturbed, but not so much a nightmare.</td>', 'You picked a hard subject to portray as a nightmare. I can see the portrait as someone who may be disturbed, but not so much a nightmare.', '2007-07-11 16:46:18.000000', NULL, 1),
(3894469, 550973, 74350, '<td valign="top">ew!...haha just kidding i give it a 0!</td>', 'ew!...haha just kidding i give it a 0!', '2007-07-11 16:47:17.000000', NULL, 1),
(3894470, 548767, 37252, '<td valign="top">I cannot be positive, but it looks like you may have used a zoom tool in editing this. If so, I''m not sure it fits into basic editing.</td>', 'I cannot be positive, but it looks like you may have used a zoom tool in editing this. If so, I''m not sure it fits into basic editing.', '2007-07-11 16:47:31.000000', NULL, 1),
(3894475, 552097, 50695, '<td valign="top">Wouldn''t it be really scary if your statistics for this challenge turned out to be exactly this? Let''s see, I''m a commentor and I have a camera, so how should I vote... hmm...</td>', 'Wouldn''t it be really scary if your statistics for this challenge turned out to be exactly this? Let''s see, I''m a commentor and I have a camera, so how should I vote... hmm...', '2007-07-11 16:48:11.000000', NULL, 1),
(3894478, 551859, 50695, '<td valign="top">It''s a bit shocking to see a bug''s face this close but it''s not quite scary, imho.</td>', 'It''s a bit shocking to see a bug''s face this close but it''s not quite scary, imho.', '2007-07-11 16:49:23.000000', NULL, 1),
(3894479, 552736, 37252, '<td valign="top">I really like the image itself. I like the color tones and the lone person standing atop the cliffs. My only problem is that the person seems to be very comfortable and calm - not portraying the nightmarish fear the title suggests.</td>', 'I really like the image itself. I like the color tones and the lone person standing atop the cliffs. My only problem is that the person seems to be very comfortable and calm - not portraying the nightmarish fear the title suggests.', '2007-07-11 16:49:29.000000', NULL, 1),
(3894484, 552633, 37252, '<td valign="top">A fear of spiders can give lots of people nightmares. I get the mightmare feeling alright, but do not care for the editing.</td>', 'A fear of spiders can give lots of people nightmares. I get the mightmare feeling alright, but do not care for the editing.', '2007-07-11 16:50:38.000000', NULL, 1),
(3894486, 551587, 50695, '<td valign="top">Nice b/w conversion on this. That''s the only thing that differentiates it from other shots of this ilk.</td>', 'Nice b/w conversion on this. That''s the only thing that differentiates it from other shots of this ilk.', '2007-07-11 16:50:41.000000', NULL, 1),
(3894490, 551933, 37252, '<td valign="top">Dropping the camera into water would be a nightmare - unless of course you have a waterproof one. :)<br/> <br/>Nice capture of the water splashing up</td>', 'Dropping the camera into water would be a nightmare - unless of course you have a waterproof one. :) Nice capture of the water splashing up', '2007-07-11 16:51:55.000000', NULL, 1),
(3894499, 550064, 50695, '<td valign="top">Good dramatic composition and a documentary sense of realism. The pointless combination of pills and blade I chalk up to dream-logic. Your title makes a poem of it.</td>', 'Good dramatic composition and a documentary sense of realism. The pointless combination of pills and blade I chalk up to dream-logic. Your title makes a poem of it.', '2007-07-11 16:52:29.000000', NULL, 1),
(3894507, 550106, 37252, '<td valign="top">A bit too much color noise here.</td>', 'A bit too much color noise here.', '2007-07-11 16:54:03.000000', NULL, 1),
(3894509, 550952, 37252, '<td valign="top">I''m not really getting a feeling of a haunted house as much as I am an old house. Perhaps if you had been able to incorporate a ghost type or things floating in the air it would be more convincing. I do like the color tones as they fit well for the feeling of an old house.</td>', 'I''m not really getting a feeling of a haunted house as much as I am an old house. Perhaps if you had been able to incorporate a ghost type or things floating in the air it would be more convincing. I do like the color tones as they fit well for the feeling of an old house.', '2007-07-11 16:55:40.000000', NULL, 1),
(3894513, 550430, 37252, '<td valign="top">What are you trapped in?</td>', 'What are you trapped in?', '2007-07-11 16:56:25.000000', NULL, 1),
(3894516, 552654, 37252, '<td valign="top">Well done with the dirt under the finger nails and all over the hand.</td>', 'Well done with the dirt under the finger nails and all over the hand.', '2007-07-11 16:57:09.000000', NULL, 1),
(3894518, 552222, 37252, '<td valign="top">Good idea - would have liked to see the spider fill more of the frame though</td>', 'Good idea - would have liked to see the spider fill more of the frame though', '2007-07-11 16:57:39.000000', NULL, 1),
(3894520, 549831, 37252, '<td valign="top">Nice cheetah pic - not sure about it fitting into the nightmares category though</td>', 'Nice cheetah pic - not sure about it fitting into the nightmares category though', '2007-07-11 16:58:13.000000', NULL, 1),
(3894524, 552938, 37252, '<td valign="top">I would try to level this more to the natural horizon, and have the  model under the covers looking as if she is truly in bed.</td>', 'I would try to level this more to the natural horizon, and have the  model under the covers looking as if she is truly in bed.', '2007-07-11 16:59:40.000000', NULL, 1),
(3894532, 552787, 37252, '<td valign="top">A nicely portrayed fear that I guess depending on where you live could be a real nightmare too.</td>', 'A nicely portrayed fear that I guess depending on where you live could be a real nightmare too.', '2007-07-11 17:00:27.000000', NULL, 1),
(3894533, 552692, 51386, '<td valign="top">Whoa, i wouldnt want to run into her in a nightmare.. shes more suited for a good dream :P Has something "grudgeish" about it. I liiike</td>', 'Whoa, i wouldnt want to run into her in a nightmare.. shes more suited for a good dream :P Has something "grudgeish" about it. I liiike', '2007-07-11 17:00:56.000000', NULL, 1),
(3894535, 552684, 37252, '<td valign="top">Good macro work. Did this give you bad dreams the night after you shot this? Maybe this creepy crawly has since made it into your house and is hiding in your bed covers? That little itch you feel tonight might actually be him/her!</td>', 'Good macro work. Did this give you bad dreams the night after you shot this? Maybe this creepy crawly has since made it into your house and is hiding in your bed covers? That little itch you feel tonight might actually be him/her!', '2007-07-11 17:01:51.000000', NULL, 1),
(3894541, 552143, 37252, '<td valign="top">Making your child cry for the sole purpose of a DPC challenge is a violation of the rules. You are hereby TOS''d.  (now wouldn''t that be a real nightmare !</td>', 'Making your child cry for the sole purpose of a DPC challenge is a violation of the rules. You are hereby TOS''d.  (now wouldn''t that be a real nightmare !', '2007-07-11 17:03:04.000000', NULL, 1),
(3894544, 552553, 37252, '<td valign="top">Ok now you did it - you''re gonna be in my dreams tonight! lol<br/> <br/>Nice work with the lighting and composition.</td>', 'Ok now you did it - you''re gonna be in my dreams tonight! lol Nice work with the lighting and composition.', '2007-07-11 17:04:07.000000', NULL, 1),
(3894548, 552837, 37252, '<td valign="top">The image is a bit too dark for my tastes</td>', 'The image is a bit too dark for my tastes', '2007-07-11 17:05:03.000000', NULL, 1),
(3894549, 552732, 80728, '<td valign="top">Cool lighting!</td>', 'Cool lighting!', '2007-07-11 17:05:08.000000', NULL, 1),
(3894551, 552978, 37252, '<td valign="top">Lighting is way too harsh</td>', 'Lighting is way too harsh', '2007-07-11 17:05:40.000000', NULL, 1),
(3894555, 552739, 37252, '<td valign="top">Everyone is dead. Don''t you know that? Life is but a dream.<br/> <br/>I like this image. I like the vignetting for the most part, though it is a bit strong along the bottom</td>', 'Everyone is dead. Don''t you know that? Life is but a dream. I like this image. I like the vignetting for the most part, though it is a bit strong along the bottom', '2007-07-11 17:07:13.000000', NULL, 1),
(3894558, 552642, 37252, '<td valign="top">Every parents worst nightmare - having their baby snatched.<br/> <br/>Good job on the lighting and composition. I really lime the sepia tones used here</td>', 'Every parents worst nightmare - having their baby snatched. Good job on the lighting and composition. I really lime the sepia tones used here', '2007-07-11 17:08:10.000000', NULL, 1),
(3894560, 552843, 37252, '<td valign="top">More silly than a nightmare.</td>', 'More silly than a nightmare.', '2007-07-11 17:08:45.000000', NULL, 1),
(3894561, 552223, 37252, '<td valign="top">Nice work with the lighting. It sets the mood perfectly as in a true nightmare</td>', 'Nice work with the lighting. It sets the mood perfectly as in a true nightmare', '2007-07-11 17:09:18.000000', NULL, 1),
(3894565, 551865, 37252, '<td valign="top">Very nicely done - lighting, composition, colors - all are good.</td>', 'Very nicely done - lighting, composition, colors - all are good.', '2007-07-11 17:09:55.000000', NULL, 1),
(3894568, 551169, 37252, '<td valign="top">Wonderful job on the lighting. This would give anyone nightmares</td>', 'Wonderful job on the lighting. This would give anyone nightmares', '2007-07-11 17:10:34.000000', NULL, 1),
(3894571, 548633, 37252, '<td valign="top">Sorry but I don''t see this as a nightmare.</td>', 'Sorry but I don''t see this as a nightmare.', '2007-07-11 17:10:57.000000', NULL, 1),
(3894573, 550008, 37252, '<td valign="top">Nice underwater shot. I think your title pulls the viewer away from the idea of a nightmare though.</td>', 'Nice underwater shot. I think your title pulls the viewer away from the idea of a nightmare though.', '2007-07-11 17:11:44.000000', NULL, 1),
(3894574, 552775, 37252, '<td valign="top">Aside from the lighting being too harsh, this is a nice macro shot.</td>', 'Aside from the lighting being too harsh, this is a nice macro shot.', '2007-07-11 17:12:14.000000', NULL, 1),
(3894576, 551970, 37252, '<td valign="top">There is a lot of noise in this image that I do not find to be complimentary.</td>', 'There is a lot of noise in this image that I do not find to be complimentary.', '2007-07-11 17:12:47.000000', NULL, 1),
(3894581, 552965, 37252, '<td valign="top">Good choice to go B/W with this. The lighting is too uneven for me - too dark along the right side</td>', 'Good choice to go B/W with this. The lighting is too uneven for me - too dark along the right side', '2007-07-11 17:14:37.000000', NULL, 1),
(3894584, 551491, 37252, '<td valign="top">Sorry but I think you''re trying to shoehorn a photo of cute toys into a Nightmare Challenge and it just doesn''t fit.</td>', 'Sorry but I think you''re trying to shoehorn a photo of cute toys into a Nightmare Challenge and it just doesn''t fit.', '2007-07-11 17:15:28.000000', NULL, 1),
(3894594, 552962, 37252, '<td valign="top">The exposure is off here due to the overpowering blast of sunlight</td>', 'The exposure is off here due to the overpowering blast of sunlight', '2007-07-11 17:16:30.000000', NULL, 1),
(3894600, 552692, 37252, '<td valign="top">Good color choices, and I like the wild movement of the girls head.</td>', 'Good color choices, and I like the wild movement of the girls head.', '2007-07-11 17:17:10.000000', NULL, 1),
(3894605, 552968, 37252, '<td valign="top">I like th snake idea - and this is a gorgeous snake. You have done well showing us the details of the snake. I think the toy being killed by the snake is a bit too silly.</td>', 'I like th snake idea - and this is a gorgeous snake. You have done well showing us the details of the snake. I think the toy being killed by the snake is a bit too silly.', '2007-07-11 17:18:12.000000', NULL, 1),
(3894612, 552851, 37252, '<td valign="top">Oh my - that would be a true nightmare! Beautiful image here. I love the colors and composition.</td>', 'Oh my - that would be a true nightmare! Beautiful image here. I love the colors and composition.', '2007-07-11 17:19:05.000000', NULL, 1),
(3894614, 551439, 37252, '<td valign="top">Good macro. Details are brought out well and focus is sharp. Lighting too harsh</td>', 'Good macro. Details are brought out well and focus is sharp. Lighting too harsh', '2007-07-11 17:19:44.000000', NULL, 1),
(3894620, 552945, 37252, '<td valign="top">Now that would be a wild nightmare - the sidewalk would suddenly be lined with hundreds of snakes. I wish there was more of the snake showing here.</td>', 'Now that would be a wild nightmare - the sidewalk would suddenly be lined with hundreds of snakes. I wish there was more of the snake showing here.', '2007-07-11 17:20:49.000000', NULL, 1),
