(3908813, 549182, 61961, '<td valign="top">A well made image, with just a slight technical problem of being able to see the prop under the bottle.  Good work by the "model."  I''m not a fan of multiple exclamation points, but I try not to let a caption color my opinion of a photo.  On the other hand, I''m a bit worried for you if spilled booze is your biggest nightmare... ;-)</td>', 'A well made image, with just a slight technical problem of being able to see the prop under the bottle.  Good work by the "model."  I''m not a fan of multiple exclamation points, but I try not to let a caption color my opinion of a photo.  On the other hand, I''m a bit worried for you if spilled booze is your biggest nightmare... ;-)', '2007-07-16 18:49:20.000000', NULL, 1),
(3908816, 551491, 61961, '<td valign="top">Cute and a good sense of humor.</td>', 'Cute and a good sense of humor.', '2007-07-16 18:50:56.000000', NULL, 1),
(3908885, 552819, 39679, '<td valign="top">Just a little dark but it''s a great shot - really awesome use of lighting.  I''d love to see you do it with a bit better exposure.</td>', 'Just a little dark but it''s a great shot - really awesome use of lighting.  I''d love to see you do it with a bit better exposure.', '2007-07-16 19:18:42.000000', NULL, 1),
(3908895, 552937, 61961, '<td valign="top">Looks kind of like a silent movie still, even without the sepia.  A little demented, like Emporer Nero playing the accordian while the city burns.</td>', 'Looks kind of like a silent movie still, even without the sepia.  A little demented, like Emporer Nero playing the accordian while the city burns.', '2007-07-16 19:22:21.000000', NULL, 1),
(3908910, 552463, 61961, '<td valign="top">I think an added element (something in the shadows?) would help convey the nightmare.<br/> <br/>Normally a negative would automatically elicit a low score from me, but considering the challenge theme I think using negative is kind of a classic - if not cliché - approach.  Btw, I took a look at the "original" and I have to say I think it is an effective photo without the negative, too!</td>', 'I think an added element (something in the shadows?) would help convey the nightmare. Normally a negative would automatically elicit a low score from me, but considering the challenge theme I think using negative is kind of a classic - if not cliché - approach.  Btw, I took a look at the "original" and I have to say I think it is an effective photo without the negative, too!', '2007-07-16 19:30:29.000000', NULL, 1),
(3908912, 552565, 61961, '<td valign="top">You know, I like everything about this except for the caption (and since I try to ignore the caption, I won''t penalize you for it).  A frightening image.</td>', 'You know, I like everything about this except for the caption (and since I try to ignore the caption, I won''t penalize you for it).  A frightening image.', '2007-07-16 19:30:48.000000', NULL, 1),
(3908914, 552282, 61961, '<td valign="top">Whoa, what a surprising image!  Not really nightmarish (to me) but certainly surreal.  Well done.</td>', 'Whoa, what a surprising image!  Not really nightmarish (to me) but certainly surreal.  Well done.', '2007-07-16 19:31:28.000000', NULL, 1),
(3909110, 552913, 43774, '<td valign="top">Wow, looks like you went through a lot of work to set this up, good job!</td>', 'Wow, looks like you went through a lot of work to set this up, good job!', '2007-07-16 21:21:34.000000', NULL, 1),
(3909252, 552834, 2158, '<td valign="top">Great timing.</td>', 'Great timing.', '2007-07-16 22:27:38.000000', NULL, 1),
(3909589, 549831, 81082, '<td valign="top">While this is a fine picture, it doesn''t aptly convey the nightmare you had. How does the picture of a cheetah show the viewer that his kind is extinct?</td>', 'While this is a fine picture, it doesn''t aptly convey the nightmare you had. How does the picture of a cheetah show the viewer that his kind is extinct?', '2007-07-17 00:35:30.000000', NULL, 1),
(3909596, 550056, 81082, '<td valign="top">The man''s expression is quite comical, but quite a bit of work could have been done to make the headline realistic.</td>', 'The man''s expression is quite comical, but quite a bit of work could have been done to make the headline realistic.', '2007-07-17 00:37:42.000000', NULL, 1),
(3909598, 552965, 81082, '<td valign="top">The tree plays well into the forebidding feeling of the picture.</td>', 'The tree plays well into the forebidding feeling of the picture.', '2007-07-17 00:38:32.000000', NULL, 1),
(3909720, 552808, 67237, '<td valign="top">completely out of focus</td>', 'completely out of focus', '2007-07-17 01:30:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3909803, 551295, 79921, '<td valign="top">Nice Job. This photo moved me. That happens maybe once a year.</td>', 'Nice Job. This photo moved me. That happens maybe once a year.', '2007-07-17 02:28:34.000000', NULL, 1),
(3910095, 552982, 64035, '<td valign="top">With an image like this, I think success and failure balance on a knife-edge (ba-doomtish). If you could have just managed to get the model''s eyes still and sharp, and everything else as it is, I''d have given this a higher mark.</td>', 'With an image like this, I think success and failure balance on a knife-edge (ba-doomtish). If you could have just managed to get the model''s eyes still and sharp, and everything else as it is, I''d have given this a higher mark.', '2007-07-17 09:48:54.000000', NULL, 1),
(3910096, 552740, 64035, '<td valign="top">Nice, and fun, but lacks dynamism for my taste. Also, the sky is unfortunate and a problem.</td>', 'Nice, and fun, but lacks dynamism for my taste. Also, the sky is unfortunate and a problem.', '2007-07-17 09:49:38.000000', NULL, 1),
(3910099, 550795, 64035, '<td valign="top">I like this image largely because it''s (with regard to the subject) so inept. It''s not a ghost. It''s a guy under a sheet. And that made me grin, which automatically gets bonus marks. Technically, I think you could have made more of the shot, perhaps by moving the "ghost" off centre a bit, or shooting from a lower angle.</td>', 'I like this image largely because it''s (with regard to the subject) so inept. It''s not a ghost. It''s a guy under a sheet. And that made me grin, which automatically gets bonus marks. Technically, I think you could have made more of the shot, perhaps by moving the "ghost" off centre a bit, or shooting from a lower angle.', '2007-07-17 09:52:56.000000', NULL, 1),
(3910101, 552958, 64035, '<td valign="top">I love the confusion in this, and the limited tones. This could have just been a mess, but I think you carried it off.</td>', 'I love the confusion in this, and the limited tones. This could have just been a mess, but I think you carried it off.', '2007-07-17 09:54:42.000000', NULL, 1),
(3910132, 550623, 64035, '<td valign="top">Good idea, however the execution is poor. Difficult thing to do on basic edit and get right.</td>', 'Good idea, however the execution is poor. Difficult thing to do on basic edit and get right.', '2007-07-17 10:22:22.000000', NULL, 1),
(3910396, 550795, 76430, '<td valign="top">I''ll give you points for meeting the challenge, but not for creativity or technical or WOW.  The flash is very harsh.  It''s not a convincing ghost.  The wall was a good choice.</td>', 'I''ll give you points for meeting the challenge, but not for creativity or technical or WOW.  The flash is very harsh.  It''s not a convincing ghost.  The wall was a good choice.', '2007-07-17 12:21:59.000000', NULL, 1),
(3910476, 551930, 39679, '<td valign="top">This is a really nice shot...much better than the standard fireworks images.  However, I''m not getting the challenge from it.</td>', 'This is a really nice shot...much better than the standard fireworks images.  However, I''m not getting the challenge from it.', '2007-07-17 12:50:27.000000', NULL, 1),
(3910533, 552669, 79921, '<td valign="top">I think you captured the nightmarish quality very well. Nice Job.</td>', 'I think you captured the nightmarish quality very well. Nice Job.', '2007-07-17 13:16:12.000000', NULL, 1),
(3910539, 552787, 79921, '<td valign="top">That does capture a very scary scene. I like the swingset in the background. I would not like to have a dream like that.</td>', 'That does capture a very scary scene. I like the swingset in the background. I would not like to have a dream like that.', '2007-07-17 13:18:49.000000', NULL, 1),
